{"taskId":"HC-901","attempt":1,"summary":"Implement Unicode-aware slug generation with compatibility normalization, lowercase conversion, ampersand expansion, and collapsed separators.","patches":[{"path":"src/hc-901.mjs","baseSha256":"A0916026D8CBCE2CDE485BFFBB1DEAA4F7EDE5BD3798660DDC046D96B69D8F79","content":"export function toSlug(value) {
  return String(value ?? '')
    .normalize('NFKC')
    .toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/[^\p{L}\p{N}]+/gu, '-')
    .replace(/^-+|-+$/g, '');
}
"}],"limitations":["Tests were not run as instructed; test/hc-901.test.mjs was not supplied."]}
